const linear = hex => Color3.FromHexString(hex).toLinearSpace();

function random(seed) {
  return () => (seed = (Math.imul(seed,1664525)+1013904223) >>> 0) / 4294967296;
}

function path(c, points, color, width=1, closed=false) {
  c.beginPath();
  points.forEach(([x,y], i) => i ? c.lineTo(x,y) : c.moveTo(x,y));
  if (closed) c.closePath();
  c.strokeStyle=color;
  c.lineWidth=width;
  c.stroke();
}

function bolt(c,x,y,size=2.8) {
  c.fillStyle='#d6d0bc'; c.fillRect(x-size,y-size+1,size*2,size*2);
  c.fillStyle='#595950'; c.beginPath(); c.arc(x,y,size,0,Math.PI*2); c.fill();
  c.fillStyle='#302f2e'; c.fillRect(x-size*.55,y-.6,size*1.1,1.2);
}

function grain(c, amplitude, seed) {
  const {width:w,height:h}=c.canvas, field=c.getImageData(0,0,w,h), data=field.data;
  const rand=random(seed);
  for (let i=0;i<data.length;i+=4) {
    const delta=(rand()+rand()-1)*amplitude;
    data[i]+=delta; data[i+1]+=delta; data[i+2]+=delta;
  }
  c.putImageData(field,0,0);
}

function grime(c,x,y,length,rand) {
  const w=1+rand()*3, g=c.createLinearGradient(x,y,x,y+length);
  g.addColorStop(0,'rgba(92,57,31,.43)'); g.addColorStop(1,'rgba(99,73,53,0)');
  c.fillStyle=g; c.beginPath(); c.moveTo(x-w,y); c.lineTo(x+w,y);
  c.lineTo(x+w*.55,y+length*.7); c.lineTo(x-1,y+length); c.fill();
}

// A matching height field keeps the pressed seams and fasteners under moving light.
function armor(c, height) {
  const n=1024, weather=random(9241);
  c.save(); c.scale(c.canvas.width/n,c.canvas.height/n);
  c.fillStyle=height?'#aaa':'#bdbdb8'; c.fillRect(0,0,n,n);
  const step=n/4;
  for (let row=0;row<4;row++) for (let col=-1;col<4;col++) {
    const x=(col+(row%2)*.52)*step*1.35, y=row*step, w=step*1.35, h=step;
    const rand=random(7291+row*3119+(col+1)*137);
    const tone=171+Math.floor(rand()*21), warm=rand()>.83;
    c.fillStyle=height?'#aaa':'rgb('+(tone+(warm?13:0))+','+(tone+2)+','+(tone+(warm?-9:5))+')';
    c.fillRect(x+1,y+1,w-2,h-2);
    path(c,[[x,y+h],[x+w,y+h],[x+w,y]],height?'#444':'#4f504e',3.0);
    path(c,[[x+1,y+2],[x+w-2,y+2]],height?'#bdbdbd':'#e1dcd0',1.5);
    const repairs=rand()>.61;
    if (!height){
      const grimeBand=c.createLinearGradient(0,y+h*.84,0,y+h);
      grimeBand.addColorStop(0,'rgba(88,77,57,0)');grimeBand.addColorStop(.86,'rgba(79,67,51,.07)');grimeBand.addColorStop(1,'rgba(81,61,39,.22)');
      c.fillStyle=grimeBand;c.fillRect(x+2,y+h*.84,w-4,h*.16);
    }
    if (repairs) {
      c.strokeStyle=height?'#747474':'#88867e';c.lineWidth=1.5;
      c.strokeRect(x+w*.46,y+h*.21,w*.34,h*.52);
    }
    for (let i=0;i<5;i++) {
      const bx=x+8+i*(w-16)/4, by=y+7;
      for (const yy of [by,y+h-8]) {
        if (height) {c.fillStyle='#727272';c.fillRect(bx-2,yy-2,4,4);}
        else bolt(c,bx,yy,2.7);
        const run=rand()*39;
        if (!height && run>7) grime(c,bx+1,yy+2,run*1.36,weather);
      }
    }
    if (!height) {
      for(let j=0;j<4;j++) {
        const bx=x+9+rand()*(w-18),by=y+h-6-rand()*3;
        const r=4+rand()*11;
        const rust=c.createRadialGradient(bx,by,0,bx,by,r);
        rust.addColorStop(0,'rgba(112,73,35,.49)');rust.addColorStop(1,'rgba(119,89,57,0)');
        c.fillStyle=rust;c.fillRect(bx-r,by-r,2*r,2*r);
        grime(c,bx,by,10+rand()*43,weather);
      }
      for (let k=0;k<115;k++) {
        const cy=y+rand()*h, cx=x+rand()*w;
        c.fillStyle=k%4?'rgba(76,68,54,.32)':'rgba(159,106,59,.54)';
        const onEdge=k<55;
        c.fillRect(onEdge?x+w-rand()*7:cx,cy,1+rand()*4,.8+rand()*4);
      }
      if ((row+col+8)%5===0) {
        c.fillStyle='#69665d';c.font='8px Consolas,monospace';
        c.fillText('INSPECT   •   07',x+15,y+h-16);
        c.fillStyle='#b99148';c.fillRect(x+16,y+h-28,18,3);
      }
    }
  }
  if (!height) {
    const rand=weather;
    for(let i=0;i<450;i++) {
      const x=rand()*n,y=rand()*n,r=3+rand()*30;
      const stain=c.createRadialGradient(x,y,0,x,y,r);
      stain.addColorStop(0,'rgba(109,95,70,.09)');stain.addColorStop(1,'rgba(120,103,78,0)');
      c.fillStyle=stain;c.fillRect(x-r,y-r,2*r,2*r);
    }
    for(let i=0;i<650;i++) {
      const x=rand()*n,y=rand()*n;
      path(c,[[x,y],[x+2+rand()*14,y-rand()*2]],i%2?'#e0dbcd88':'#716c6266',.65);
    }
    grain(c,17,387);
  }
  c.restore();
}

function normalMap(c) {
  armor(c,true);
  const w=c.canvas.width,h=c.canvas.height,source=c.getImageData(0,0,w,h).data;
  const normal=c.createImageData(w,h),pixels=normal.data;
  const at=(x,y)=>source[4*(((y+h)%h)*w+(x+w)%w)]/255;
  for(let y=0;y<h;y++) for(let x=0;x<w;x++){
    const dx=(at(x-1,y)-at(x+1,y))*.66,dy=(at(x,y-1)-at(x,y+1))*.66;
    const mag=Math.hypot(dx,dy,1),i=4*(y*w+x);
    pixels[i]=128+127*dx/mag;
    pixels[i+1]=128-127*dy/mag;
    pixels[i+2]=128+127/mag;
    pixels[i+3]=255;
  }
  c.putImageData(normal,0,0);
}

function apron(c) {
  const n=1024,rand=random(562);
  c.save();c.scale(c.canvas.width/n,c.canvas.height/n);
  c.fillStyle='#58585a';c.fillRect(0,0,n,n);
  for(let j=0;j<7;j++) for(let i=-1;i<7;i++){
    const x=i*166+(j%2)*60,y=j*153,t=73+Math.floor(rand()*17);
    c.fillStyle='rgb('+t+','+t+','+(t+2)+')';c.fillRect(x+2,y+2,163,150);
    path(c,[[x,y+152],[x+140,y+152],[x+165,y+127],[x+165,y]],'#373b40',2);
    for(const bx of [x+7,x+152]) for(const by of [y+7,y+139])bolt(c,bx,by,2);
    if((j+i+2)%3===0){
      c.strokeStyle='#969087';c.lineWidth=1;c.strokeRect(x+19,y+20,38,24);
      c.fillStyle='#44464a';c.fillRect(x+23,y+29,8,3);
    }
  }
  const xy=([x,z])=>{const [u,v]=padUV([x,z]);return [u*n,(1-v)*n];};
  const margin=APRON.map(([x,z])=>xy([x*.945,BERTH_RADIUS+(z-BERTH_RADIUS)*.934]));
  path(c,margin,'#b1975d',3.8,true);
  for(const x of [-3.1,0,3.1])path(c,[xy([x,16]),xy([x,26.5])],'#b09a6b99',1.6);
  for(const z of [17.7,20.2,22.7,25.2])path(c,[xy([-6.4,z]),xy([6.4,z])],'#b09a6baa',1.6);
  for(const x of [-3.1,0,3.1]) for(const z of [17.7,20.2,22.7,25.2]){
    const [px,py]=xy([x,z]);c.strokeStyle='#c6a667';c.lineWidth=2;
    c.beginPath();c.arc(px,py,8,0,2*Math.PI);c.stroke();
  }
  const [px,py]=xy([-3.6,25.3]);c.fillStyle='#c0ae83';c.font='bold 17px Consolas,monospace';c.fillText('PT / SERVICE',px,py);
  // Tire rub and a soft contact tone complement the real directional shadow.
  for (const [x,z] of GEAR){
    const [cx,cy]=xy([x*CUTTER_SCALE,BERTH_RADIUS+z*CUTTER_SCALE]);
    const g=c.createRadialGradient(cx,cy,0,cx,cy,17);g.addColorStop(0,'#16191bdd');g.addColorStop(1,'#25282a00');
    c.fillStyle=g;c.fillRect(cx-17,cy-17,34,34);
  }
  for(let i=0;i<2400;i++){
    const x=rand()*n,y=rand()*n;c.fillStyle=i%3?'#92908a61':'#38383a77';
    c.fillRect(x,y,1+rand()*7,.6+rand()*1.4);
  }
  for(const edge of margin){
    for(let k=0;k<9;k++)grime(c,edge[0]+(rand()-.5)*88,edge[1]+(rand()-.5)*48,14+rand()*72,rand);
  }
  for(let i=0;i<46;i++){
    const x=rand()*n,y=rand()*n,size=13+rand()*43;
    const smudge=c.createRadialGradient(x,y,1,x,y,size);
    smudge.addColorStop(0,'rgba(34,33,30,.20)');smudge.addColorStop(1,'rgba(40,39,36,0)');
    c.fillStyle=smudge;c.fillRect(x-size,y-size,size*2,size*2);
  }
  grain(c,21,15);
  c.restore();
}

// Eight occupied workstations share one atlas. The mullions and inset returns remain geometry.
function rooms(c,emission) {
  const w=128,h=128;
  const rand=random(779);
  c.save();c.scale(c.canvas.width/(8*w),c.canvas.height/h);
  for(let j=0;j<8;j++){
    const light=[.94,.67,1,.42,.85,.98,.64,.88][j],ox=(j%3-1)*13;
    c.save();c.translate(j*w,0);c.beginPath();c.rect(0,0,w,h);c.clip();
    const color=(r,g,b)=>'rgb('+[r,g,b].map(v=>Math.round(v*light))+')';
    const polygon=(points,ink)=>{
      c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=ink;c.fill();
    };
    const mid=w*.5+ox;
    const wall=c.createLinearGradient(0,0,w,h);
    wall.addColorStop(0,emission?'#030609':'#25313a');
    wall.addColorStop(.49,color(112,70,31));wall.addColorStop(.78,color(173,105,46));wall.addColorStop(1,'#161d24');
    c.fillStyle=wall;c.fillRect(0,0,w,h);
    polygon([[0,0],[w,0],[mid+33,32],[mid-29,32]],emission?'#0e0d0c':'#383b3a');
    polygon([[0,h],[mid-30,83],[mid+33,83],[w,h]],emission?'#302418':'#4c4339');
    for(const y of [38,58,79])path(c,[[0,y-13],[mid-29,y],[mid+32,y],[w,y-10]],'#433b32',1.2);
    for(const x of [5,21,95,118])path(c,[[x,0],[mid+(x-mid)*.54,32],[mid+(x-mid)*.54,84]],'#373635',2);
    const lx=mid-24,ly=23+(j%3)*2;
    const bloom=c.createRadialGradient(mid,ly,1,mid,ly,39);
    bloom.addColorStop(0,color(245,173,80));bloom.addColorStop(.36,'rgba(241,151,44,.28)');bloom.addColorStop(1,'rgba(213,145,59,0)');
    c.fillStyle=bloom;c.fillRect(mid-39,ly-39,78,78);
    c.fillStyle=color(249,169,72);c.fillRect(lx,ly,47,4.5);
    c.fillStyle='#fff0bd';c.fillRect(lx+1,ly+.5,45,2.0);
    for(let k=0;k<2;k++){
      const x=14+k*58+rand()*11,y=53+rand()*13;
      polygon([[x,y],[x+30,y-2],[x+28,y+15],[x-2,y+18]],'#252b2e');
      c.fillStyle=k?'#343e3f':'#514934';c.fillRect(x+2,y+2,23,9);
      for(let n=0;n<7;n++){
        c.fillStyle=n%3?'#a78952':'#c5c19a';c.fillRect(x+4+(n%4)*4,y+4+Math.floor(n/4)*3,1+rand()*3,1);
      }
      polygon([[x-6,y+19],[x+27,y+16],[x+35,y+19],[x-2,y+23]],color(156,122,75));
      c.fillStyle='#1e2326';c.fillRect(x+1,y+23,3,19);c.fillRect(x+27,y+20,2,15);
      const sx=x+8+(j+k)%3*3,sy=y+14;
      c.fillStyle='#555047';c.beginPath();c.roundRect(sx,sy,13,20,3);c.fill();
      c.fillStyle=emission?'#141719':'#292e31';c.beginPath();c.roundRect(sx+1,sy+.7,11,18,3);c.fill();
      c.fillRect(sx-2,sy+19,15,3);c.fillRect(sx+5,sy+22,2,10);
    }
    if(!emission){
      const sky=c.createLinearGradient(0,0,w*.44,h);
      sky.addColorStop(0,'#9baec29c');sky.addColorStop(.38,'#687d913d');sky.addColorStop(.76,'#28354018');sky.addColorStop(1,'#161d2655');
      c.fillStyle=sky;c.fillRect(0,0,w,h);
    }
    c.restore();
  }
  c.restore();
}

function createFinishes(scene) {
  function texture(name,w,h,paint) {
    const t=new DynamicTexture(name,{width:w,height:h},scene,true,Texture.TRILINEAR_SAMPLINGMODE);
    t.wrapU=t.wrapV=Texture.WRAP_ADDRESSMODE;t.anisotropicFilteringLevel=8;
    paint(t.getContext());t.update();return t;
  }
  function metal(name,hex,metallic,roughness,map,tile=5) {
    const m=new PBRMaterial(name,scene);
    m.albedoColor=linear(hex);m.metallic=metallic;m.roughness=roughness;m.metadata={tile};
    if(map)m.albedoTexture=map;
    return m;
  }
  // The plate map repeats every few units, so at 512 a texel stays under a pixel at the nearest view.
  // The deck's map covers a whole apron and a room a whole window, so those keep their size.
  const skin=texture('Riveted plates and wear',512,512,c=>armor(c,false));
  const relief=texture('Panel recess normals',512,512,normalMap);
  const plating=metal('Weathered porcelain armor','#edf0f3',.36,.60,skin,6.2);
  relief.gammaSpace=false;
  plating.bumpTexture=relief;
  const structural=metal('Load-bearing steel','#a7a5a0',.69,.46,skin,3.7);
  const dark=metal('Graphite machinery','#545960',.67,.50,skin,3.2);
  const gallery=metal('Inhabited pressure windows','#e7e9e6',.25,.18,texture('Glazed rooms',1024,128,c=>rooms(c,false)));
  gallery.emissiveTexture=texture('Lit consoles and cabin lights',1024,128,c=>rooms(c,true));
  gallery.emissiveColor=new Color3(1.55,1.38,1.08);
  const lamp=metal('Work lights','#ffe0ae',.1,.23);lamp.emissiveColor=new Color3(3.1,1.45,.50);
  return {
    plating,structural,dark,gallery,lamp,
    deck:metal('Landing deck','#efeae0',.23,.79,texture('Drydock striping and scuffs',1024,1024,apron)),
    seam:metal('Recessed expansion joints','#262b30',.48,.62),
    enamel:metal('Ivory edge castings','#c8c6ba',.38,.45),
    brass:metal('Ochre conduit and rails','#bf9147',.64,.39),
    pipe:metal('Distribution lines','#889095',.78,.38),
    foil:metal('Insulated service packs','#c1c2bd',.82,.36),
    olive:metal('Freight containers','#797f68',.34,.67,skin,2.7),
    tire:metal('Landing tires','#252626',.07,.86),
  };
}
return { createFinishes };
